let lang='ko';
function tr(value){if(lang!=='en')return String(value);let out=String(value);for(const [ko,en] of PHRASES)out=out.replaceAll(ko,en);return out.replace(/([0-9][0-9,.]*)개/g,'$1').replace(/([0-9][0-9,.]*)건/g,'$1 records').replace(/([0-9][0-9,.]*)회/g,'$1 times').replace(/([0-9][0-9,.]*)자/g,'$1 chars')}
function applyLanguage(){document.documentElement.lang=lang;for(const x of document.querySelectorAll('[data-en-aria]')){if(!x.dataset.koAria)x.dataset.koAria=x.getAttribute('aria-label');x.setAttribute('aria-label',lang==='en'?x.dataset.enAria:x.dataset.koAria)}document.title=lang==='en'?'Jev Gate · Execution overview':'Jev Gate · 실행 관측';for(const x of document.querySelectorAll('[data-i18n]')){if(!x.dataset.ko)x.dataset.ko=x.textContent;x.textContent=lang==='en'?(EN[x.dataset.i18n]||x.dataset.ko):x.dataset.ko}$('search').placeholder=lang==='en'?'Search run ID or feature':'실행 ID 또는 기능 검색';$('theme').textContent=lang==='en'?(document.documentElement.dataset.theme==='dark'?'Light':'Dark'):(document.documentElement.dataset.theme==='dark'?'화이트':'다크');$('theme').setAttribute('aria-label',lang==='en'?'Change theme':'테마 전환');$('language').textContent=lang==='en'?'KO':'EN';$('language').setAttribute('aria-label',lang==='en'?'Change language':'언어 전환');$('pause').textContent=lang==='en'?(paused?'Resume live':'Pause live'):(paused?'실시간 재개':'실시간 일시정지');$('connection').textContent=tr($('connection').dataset.label||'연결 중');if(data)draw(data)}
const $=id=>document.getElementById(id);
const el=(tag,cls,value)=>{const x=document.createElement(tag);if(cls)x.className=cls;if(value!==undefined)x.textContent=tr(String(value));return x};
const time=s=>{const d=new Date(s);return Number.isNaN(d.getTime())?'—':d.toLocaleTimeString(lang==='en'?'en-US':'ko-KR',{hour12:false})};
const date=s=>{const d=new Date(s);return Number.isNaN(d.getTime())?'—':d.toLocaleString(lang==='en'?'en-US':'ko-KR',{hour12:false})};
const ms=n=>Number.isFinite(n)?Math.round(n)+' ms':'—';
const lane={jev:'Jev',policy:'정책',host:'호스트',local:'로컬'};
const state={active:'진행 중',attention:'확인 필요',done:'완료',error:'오류',unconfirmed:'결과 미확인',skipped:'건너뜀'};
const source={codex:'Codex',gate:'Gate',router:'Router',compact:'Compact',output:'Output',evidence:'Evidence'};
let data=null,pending=null,selectedRun=null,selectedStep=null,selectedFeature='all',stateFilter='all',query='',paused=false;const seenFeatures=new Map();
const inWindow=s=>{const n=Number($('window').value);return !n||Date.now()-Date.parse(s)<=n};
const visibleRuns=ops=>ops.runs.filter(r=>inWindow(r.lastAt)&&(selectedFeature==='all'||r.steps.some(s=>!s.lifecycle&&s.feature===selectedFeature))&&(stateFilter==='all'||r.state===stateFilter)&&(!query||[r.id,r.title,r.mode,...r.steps.map(s=>s.feature)].join(' ').toLowerCase().includes(query)));
function nav(ops){const root=$('nav');root.replaceChildren();const entries=[{id:'all',label:'전체 실행',count:ops.runs.length,state:'observed'},...ops.features];for(const f of entries){const b=el('button',f.id===selectedFeature?'selected':'');b.type='button';b.dataset.feature=f.id;b.append(el('span','pin '+f.state),document.createTextNode(tr(f.label)),el('span','count',f.count));root.append(b)}}
const featureInfo={admission:['Gate A','요청의 실행 형태 선택','Jev'],planning:['계획','작업 그래프와 검사','호스트'],allocation:['Gate B','플래너·워커 등급','Jev'],workers:['워커','Agent 실행과 수락','호스트'],guard:['도구 가드','루트 호출 허용 검사','정책'],lean:['Lean','문맥 선택 → packet → executor','Jev'],router:['Router','모델·effort 선택','Jev'],compact:['Compact','요약 대신 digest 구성','로컬'],output:['Output','Vitest 로그 접기','로컬'],evidence:['Evidence','근거 후보 → 판정 → 결과','Jev']};
const GUIDE={
admission:{what:['요청을 직접 처리할지, 작업을 위임할지 결정합니다.','Decides whether the request stays with the root or is delegated.'],when:['적격한 루트 사용자 요청이 들어올 때 실행합니다.','Runs on an eligible root user request.'],jev:['Jev가 요청의 형태를 빠르게 분류합니다. 코드가 확률과 제약을 보고 최종 경로를 정합니다.','Jev quickly classifies the request. Code uses its typed answer, probabilities, and constraints to choose the path.'],out:['직접 처리 또는 단일 워커·계획 기반 위임으로 이어집니다. 불확실하면 원래 경로를 유지합니다.','The root continues directly, or one worker or a planned job is delegated. Uncertainty preserves the original path.']},
planning:{what:['위임한 작업의 의존 관계와 필수 검사를 만듭니다.','Builds task dependencies and required checks for delegated work.'],when:['Gate A가 계획 기반 위임을 고른 뒤 플래너가 실행됩니다.','A planner runs after Gate A selects planned delegation.'],jev:['계획 자체는 호스트 플래너가 만듭니다. 선택적 계획 해석만 Jev에 묻고 결과는 자문으로 사용합니다.','The host planner creates the plan. Optional Jev interpretation is advisory.'],out:['코드가 작업 그래프와 계약을 검증한 뒤 준비된 작업만 엽니다.','Code validates the task graph and contracts, then opens only ready tasks.']},
allocation:{what:['플래너·워커에 사용할 등급을 선택합니다.','Selects a tier for a planner or worker.'],when:['위임된 Agent 호출이 실행되기 직전에 판단합니다.','Runs just before an eligible delegated Agent call.'],jev:['Jev가 원문과 작업 근거를 보고 등급을 제안합니다. 계획이 있으면 작업 계약과 선행 결과도 사용합니다.','Jev proposes a tier from the original request and task evidence, including contracts and predecessor summaries when a plan exists.'],out:['코드가 상향 근거와 제약을 검사해 호출 모델을 정합니다. 불확실하면 원래 모델을 유지합니다.','Code checks upgrade grounds and constraints before choosing the called model. Uncertainty preserves it.']},
workers:{what:['Agent가 실제로 수행한 일과 수락 조건을 추적합니다.','Tracks the Agent work and whether it met acceptance conditions.'],when:['플래너·워커 호출, 반환, 실패 이벤트를 기록합니다.','Records planner and worker dispatch, return, and failure events.'],jev:['Gate B 등급 판정과 연결됩니다. 작업 수락은 Jev가 아닌 코드가 결정합니다.','Links to Gate B tier choice. Code, not Jev, determines task acceptance.'],out:['요청한 모델과 관측한 모델, 검사 결과, 다음에 열리는 작업을 구분해 보여줍니다.','Shows requested versus observed model, checks, and tasks that become ready.']},
guard:{what:['위임 중 루트가 직접 사용하는 도구를 제한합니다.','Limits root tool use during delegated work.'],when:['활성 위임 작업의 루트 도구 호출마다 적용합니다.','Applies to each root tool call in an active delegated job.'],jev:['Jev 호출이 없습니다. 코드의 허용 목록과 예산이 판정합니다.','No Jev call. Code checks the allowlist and budget.'],out:['허용·거절과 예산 소진을 기록합니다. 자식 Agent 호출은 이 가드 대상이 아닙니다.','Records allowed and denied calls and budget exhaustion. Child Agent calls are outside this guard.']},
lean:{what:['긴 이전 문맥에서 필요한 부분만 executor에 인계합니다.','Hands only relevant prior context to one executor.'],when:['별도 lean 모드에서 적격한 Agent 호출 전에 실행합니다.','Runs before an eligible Agent call in separate lean mode.'],jev:['Jev가 이전 대화 그룹의 관련성을 한 번에 판단합니다.','Jev judges relevance of prior conversation groups in one batch.'],out:['코드가 생략이 실제로 있는지 확인하고 packet을 만듭니다. Gate A·B나 플래너는 실행하지 않습니다.','Code builds a packet only when it really omits context. Gate A, B, and the planner do not run.']},
router:{what:['호스트의 모델 또는 effort 선택을 조정합니다.','Adjusts host model or effort selection.'],when:['루트 턴과 상속형 내장 subagent 이벤트에서 실행할 수 있습니다.','May run for root turns and inherited built-in subagent events.'],jev:['필요한 경우 Jev가 모델·effort에 관한 선택형 질문에 답합니다.','When needed, Jev answers typed questions about model and effort.'],out:['제안한 설정과 호스트에서 실제로 관측한 설정을 따로 보여줍니다.','Separates proposed settings from those actually observed in the host.']},
compact:{what:['자동 문맥 압축에서 오래된 내용을 짧은 digest로 구성합니다.','Builds a short digest of older context at auto-compaction.'],when:['호스트의 압축 이벤트에서 조건이 맞으면 실행합니다.','Runs when host compaction conditions are met.'],jev:['Jev를 호출하지 않습니다. 로컬 추출 규칙으로 digest를 만듭니다.','Does not call Jev. Local extractive rules build the digest.'],out:['digest를 적용하거나 호스트의 기본 압축으로 넘긴 결과를 보여줍니다.','Shows whether the digest was applied or host compaction handled it.']},
output:{what:['반복되는 성공 Vitest 출력만 간결하게 접습니다.','Folds repeated lines in a successful Vitest log.'],when:['조건에 맞는 Bash 결과가 저장된 파일로 반환될 때 실행합니다.','Runs for a qualifying Bash result backed by a saved log file.'],jev:['Jev를 호출하지 않습니다. 정해진 파서가 출력 형태를 검사합니다.','Does not call Jev. A fixed parser checks the output shape.'],out:['접힌 로그와 원본을 유지한 경우를 구분합니다. 일반 CLI나 실패 로그는 접지 않습니다.','Distinguishes folded logs from preserved output. Other CLI and failure logs stay unchanged.']},
evidence:{what:['프로젝트 파일에서 근거를 찾아 검증된 결과로 돌려줍니다.','Finds evidence in project files and returns verified results.'],when:['Evidence MCP 검색 요청이 들어올 때 실행합니다.','Runs on an Evidence MCP search request.'],jev:['의미 검색 후보에 한해 Jev가 관련성을 판정합니다. 정확한 심볼 조회와 재읽기는 로컬입니다.','Jev judges semantic search candidates. Exact symbol lookup and read-back stay local.'],out:['검색 후보, 원격 판정·캐시, 재검증, 반환 범위를 보여줍니다.','Shows candidates, remote judgment or cache, re-verification, and result coverage.']}
};
