  const legacy=card('01 / Gate',label('요청 분류 · 위임 · 수락','Classify · delegate · accept'),['admission','planning','allocation','workers','guard']);
  const main=el('div','map-flow legacy-map');main.append(makeNode('admission','01 / JEV'));
  const fork=el('span','path-break');fork.append(el('span','direct',label('직접 → root 계속','Direct → root')),el('span','delegate',label('단일 워커 →','One worker →')),el('span','direct',label('계획 기반 ↓','Planned path ↓')));main.append(fork,makeNode('allocation','WORKER / JEV'),edge(),makeNode('workers','EXECUTE / ACCEPT'));legacy.append(main);
