  const mods=card(data?.host==='codex'?'03 / Host policies':'03 / Function Mods',label('호스트 이벤트별 독립 처리','Independent host event paths'),['router','compact','output']);
  const parallel=el('div','parallel-map');for(const [id,n] of [['router','MODEL / EFFORT'],['compact','CONTEXT'],['output','TOOL OUTPUT']])parallel.append(makeNode(id,n));mods.append(parallel);grid.append(mods);
