  root.append(grid);const legend=el('div','pipeline-legend');for(const [cls,ko,en] of [['seen','관측됨','Observed'],['selected-pin','선택한 실행','Selected run'],['','기록 대기','No record']]){const x=el('span');x.append(el('i',cls),document.createTextNode(label(ko,en)));legend.append(x)}root.append(legend);
  const focus=selectedFeature==='all'?(run?.steps.at(-1)?.feature||'admission'):selectedFeature;const info=GUIDE[focus],feature=ops.features.find(f=>f.id===focus);if(info&&feature){const guide=el('div','feature-guide');const head=el('div','feature-guide-head');head.append(el('small','',label('선택한 기능 · 설명','SELECTED CAPABILITY')),el('strong','',feature.label),el('span','',feature.state==='observed'?label(feature.count+'개 기록 · 마지막 '+time(feature.lastAt),feature.count+' events · last '+time(feature.lastAt)):feature.state==='unsupported'?label('이 호스트에서 미지원','Unsupported on this host'):feature.capability?.mode==='observe'?label('관측 전용','Observation only'):feature.state==='unavailable'?label('기록원 미설정','Source unavailable'):label('실행 기록 대기','Awaiting execution record')));guide.append(head);for(const [title,value] of (feature.capability?[[label('지원 상태','SUPPORT'),[{active:'사용 가능',observe:'관측 전용',connect:'Codex 세션 연결 필요',unsupported:'이 호스트에서 미지원'}[feature.capability.mode],{active:'Available',observe:'Observation only',connect:'Connect Codex session',unsupported:'Unsupported'}[feature.capability.mode]]],[label('Codex 동작','CODEX BEHAVIOR'),[feature.capability.ko,feature.capability.en]],[label('기록 기준','OBSERVATION'),["호스트 이벤트는 Jev 호출·계약 수락·토큰 절감의 증거가 아닙니다.","Host events are not evidence of Jev calls, accepted contracts, or token savings."]]]:[[label('무엇을 하나요','WHAT IT DOES'),info.what],[label('언제 실행되나요','WHEN IT RUNS'),info.when],[label('Jev와 결과','JEV AND OUTCOME'),[info.jev[lang==='en'?1:0]+' '+info.out[lang==='en'?1:0],'']]])){const cell=el('div','feature-guide-cell');cell.append(el('small','',title),el('p','',Array.isArray(value)&&value[1]?value[lang==='en'?1:0]:value[0]));guide.append(cell)}root.append(guide)}
